function encontrarPrimeiroNegativo(numeros) {
  let indice = -1;

  for (let i = 0; i < numeros.length; i++) {
    if (numeros[i] < 0) {
      indice = i;
      break;
    }
  }

  return indice;
}

console.log(encontrarPrimeiroNegativo([4, 7, -2, 9])); // 2
console.log(encontrarPrimeiroNegativo([4, 7, 2, 9])); // -1

function somarPares(valores) {
  let soma = 0;

  for (const valor of valores) {
    if (typeof valor !== 'number' || valor % 2 !== 0) {
      continue;
    }
    soma += valor;
  }

  return soma;
}

console.log(somarPares([1, 2, '3', 4, 5, 6, null, 8])); // 20

function encontrarPar(listaA, listaB, alvo) {
  let resultado = null;

  procura: for (const valorA of listaA) {
    for (const valorB of listaB) {
      if (valorA + valorB === alvo) {
        resultado = [valorA, valorB];
        break procura;
      }
    }
  }

  return resultado;
}

console.log(encontrarPar([1, 2, 3], [10, 20, 30], 23)); // [3, 20]
console.log(encontrarPar([1, 2], [10, 20], 100)); // null

function validarNotas(turmas) {
  let resultado = { valido: true };

  turmaLoop: for (let t = 0; t < turmas.length; t++) {
    const turma = turmas[t];

    if (turma[0] === 'ISENTA') {
      continue turmaLoop;
    }

    for (let a = 0; a < turma.length; a++) {
      const nota = turma[a];
      if (typeof nota !== 'number' || nota < 0 || nota > 20) {
        resultado = { valido: false, turma: t, aluno: a };
        break turmaLoop;
      }
    }
  }

  return resultado;
}

console.log(validarNotas([[15, 18, 20], ['ISENTA'], [10, 25, 12]]));
// { valido: false, turma: 2, aluno: 1 }

console.log(validarNotas([[15, 18, 20], ['ISENTA'], [10, 12, 14]]));
// { valido: true }
